-- Generated by SECS 2R. Keep this script beside its WAV files.
-- ReaScript API: https://www.reaper.fm/sdk/reascript/reascripthelp.html
-- FILELDR protocol reference: https://forum.cockos.com/showthread.php?t=234517
-- This implementation does not use SWS or other extensions.
local function message(text)
  reaper.ShowMessageBox(text, "SECS 2R", 0)
end

local source = reaper.GetSelectedTrack(0, 0)
if not source then
  message("Select the source track first. Its channels must follow the input order in routing.json.")
  return
end
local marker = "P_EXT:SECS2R_CONVOLUTION"
local _, selected_marker = reaper.GetSetMediaTrackInfo_String(source, marker, "", false)
if selected_marker ~= "" or reaper.GetMediaTrackInfo_Value(source, "I_FOLDERDEPTH") > 0 then
  message("Select a source track outside the SECS 2R folder, not a folder parent.")
  return
end
if input_channels > 128 or output_channels > 128 then
  message("This routing exceeds REAPER's limit of 128 track channels.")
  return
end

-- debug.getinfo refers to this file even when a test harness uses dofile.
local script = debug.getinfo(1, "S").source:sub(2)
local directory = script:match("^(.*[/\\])")
if not directory then
  message("Cannot find the bundle folder. Load the script from its saved file.")
  return
end
for _, path in ipairs(paths) do
  path.file = directory .. path.wav
  -- REAPER's configuration tokenizer accepts a double-quoted file path.
  -- Reject quotes and line breaks instead of injecting configuration entries.
  if path.file:find('["\r\n]') or not reaper.file_exists(path.file) then
    message("An impulse response is missing or its folder name contains a quote or line break. Keep the script and WAV files together in another folder.")
    return
  end
end

local owner = reaper.GetTrackGUID(source)
local old = {}
local depth = 0
for i = 0, reaper.CountTracks(0) - 1 do
  local track = reaper.GetTrack(0, i)
  local _, tag = reaper.GetSetMediaTrackInfo_String(track, marker, "", false)
  if tag == owner then
    old[#old + 1] = track
    depth = depth + reaper.GetMediaTrackInfo_Value(track, "I_FOLDERDEPTH")
  elseif depth ~= 0 then
    message("The previous SECS 2R folder contains another track. Move that track out before replacing the correction.")
    return
  end
end
if depth ~= 0 then
  message("The previous SECS 2R folder structure has changed. Undo that change before replacing the correction.")
  return
end

local created = {}
local original_channels = reaper.GetMediaTrackInfo_Value(source, "I_NCHAN")
local original_main = reaper.GetMediaTrackInfo_Value(source, "B_MAINSEND")
local function set_track(track, key, value)
  assert(reaper.SetMediaTrackInfo_Value(track, key, value), "track setting: " .. key)
end
local function new_track(index, name, channels)
  -- Do not load the user's default track FX or send settings.
  reaper.InsertTrackAtIndex(index, false)
  local track = assert(reaper.GetTrack(0, index), "new track")
  created[#created + 1] = track
  assert(reaper.GetSetMediaTrackInfo_String(track, "P_NAME", name, true))
  assert(reaper.GetSetMediaTrackInfo_String(track, marker, owner, true))
  set_track(track, "I_NCHAN", channels)
  set_track(track, "I_FOLDERDEPTH", 0)
  set_track(track, "D_VOL", 1)
  set_track(track, "D_PAN", 0)
  set_track(track, "D_WIDTH", 1)
  set_track(track, "D_PANLAW", 1)
  set_track(track, "I_PANMODE", 0)
  set_track(track, "B_MAINSEND", 0)
  set_track(track, "B_MUTE", 0)
  return track
end
local function send(from, to, input, output)
  local index = reaper.CreateTrackSend(from, to)
  assert(index >= 0, "new send")
  local settings = {
    I_SRCCHAN = 1024 + input - 1, -- mono, zero-based source offset
    I_DSTCHAN = 1024 + output - 1, -- mono, zero-based destination offset
    I_SENDMODE = 3, -- post-FX, pre-fader: do not apply source/path pan law
    I_MIDIFLAGS = 31, -- no MIDI
    D_VOL = 1, D_PAN = 0, D_PANLAW = 1,
    B_MUTE = 0, B_PHASE = 0, B_MONO = 0,
  }
  for key, value in pairs(settings) do
    assert(reaper.SetTrackSendInfo_Value(from, 0, index, key, value), "send setting: " .. key)
  end
end
local function convolver(track, file)
  local fx = reaper.TrackFX_AddByName(track, "ReaVerb (Cockos)", false, -1)
  assert(fx >= 0, "ReaVerb unavailable")
  -- A saved default preset must not introduce generators or gain/trim modules.
  assert(reaper.TrackFX_SetPresetByIndex(track, fx, -2), "ReaVerb factory preset")
  local has_item, initial_item = reaper.TrackFX_GetNamedConfigParm(track, fx, "ITEM0")
  assert(not has_item or initial_item == "", "unexpected ReaVerb factory preset")
  -- 60 selects the normal file-loader gain mode (no normalization or -18 dB).
  local config = 'FILELDR "' .. file .. '" 60'
  assert(reaper.TrackFX_SetNamedConfigParm(track, fx, "ITEM0", config))
  assert(reaper.TrackFX_SetNamedConfigParm(track, fx, "DONE", ""))
  local loaded, value = reaper.TrackFX_GetNamedConfigParm(track, fx, "ITEM0")
  assert(loaded and value == config, "ReaVerb file configuration was not retained")
  local has_extra, extra = reaper.TrackFX_GetNamedConfigParm(track, fx, "ITEM1")
  assert(not has_extra or extra == "", "extra ReaVerb module")

  -- ReaVerb uses linear amplitude for Wet/Dry, not dB: 1 is 0 dB, 0 is off.
  -- Resolve parameter names rather than assuming indices. Reject incompatible FX.
  local settings = {Wet = 1, Dry = 0, ["Pre-verb"] = 0, Width = 1,
    Pan = 0.5, ["ZL mode"] = 1, ["LL mode"] = 0}
  for i = 0, reaper.TrackFX_GetNumParams(track, fx) - 1 do
    local found, name = reaper.TrackFX_GetParamName(track, fx, i, "")
    if found and settings[name] ~= nil then
      local expected = settings[name]
      assert(reaper.TrackFX_SetParamNormalized(track, fx, i, expected))
      assert(math.abs(reaper.TrackFX_GetParamNormalized(track, fx, i) - expected) < 1e-7)
      settings[name] = nil
    end
  end
  assert(next(settings) == nil, "ReaVerb parameters unavailable")
  local wet = reaper.TrackFX_GetParamFromIdent(track, fx, ":wet")
  assert(wet >= 0 and reaper.TrackFX_SetParamNormalized(track, fx, wet, 1))
  reaper.TrackFX_SetEnabled(track, fx, true)
  -- Only channel 1 enters and leaves this mono path; no stereo summing gain.
  for pin = 0, 1 do
    local mask = pin == 0 and 1 or 0
    assert(reaper.TrackFX_SetPinMappings(track, fx, 0, pin, mask, 0))
    assert(reaper.TrackFX_SetPinMappings(track, fx, 1, pin, mask, 0))
  end
end

reaper.Undo_BeginBlock()
reaper.PreventUIRefresh(1)
local ok, detail = xpcall(function()
  local index = math.floor(reaper.GetMediaTrackInfo_Value(source, "IP_TRACKNUMBER"))
  local folder = new_track(index, "SECS 2R " .. design_name, output_channels)
  set_track(folder, "B_MUTE", 1)
  -- Set folder depths after insertion, so REAPER cannot move an existing closure.
  local path_tracks = {}
  for i, path in ipairs(paths) do
    path_tracks[i] = new_track(index + i, path.name, 2)
    convolver(path_tracks[i], path.file)
  end
  local bus = new_track(index + #paths + 1, "SECS 2R Output", output_channels)
  set_track(folder, "I_FOLDERDEPTH", 1)
  set_track(bus, "I_FOLDERDEPTH", -1)
  set_track(bus, "C_MAINSEND_OFFS", 0)
  set_track(bus, "C_MAINSEND_NCH", 0)
  set_track(bus, "B_MAINSEND", 1)
  set_track(folder, "C_MAINSEND_OFFS", 0)
  set_track(folder, "C_MAINSEND_NCH", 0)
  set_track(folder, "B_MAINSEND", 1)
  set_track(source, "I_NCHAN", math.max(original_channels, input_channels))
  for i, path in ipairs(paths) do
    send(source, path_tracks[i], path.input, 1)
    send(path_tracks[i], bus, 1, path.output)
  end
  set_track(source, "B_MAINSEND", 0)
  set_track(folder, "B_MUTE", 0)
  -- Only delete the previous set after every fallible setting has succeeded.
  for i = #old, 1, -1 do reaper.DeleteTrack(old[i]) end
end, debug.traceback)
if not ok then
  for i = #created, 1, -1 do reaper.DeleteTrack(created[i]) end
  reaper.SetMediaTrackInfo_Value(source, "I_NCHAN", original_channels)
  reaper.SetMediaTrackInfo_Value(source, "B_MAINSEND", original_main)
  reaper.ShowConsoleMsg("SECS 2R: " .. tostring(detail) .. "\n")
end
reaper.PreventUIRefresh(-1)
reaper.TrackList_AdjustWindows(false)
reaper.UpdateArrange()
reaper.Undo_EndBlock("SECS 2R convolution routing", -1)
if ok then
  message("Correction tracks are ready. The source track's master/parent send is now off. Route the SECS 2R Output bus to your outputs and use a 48000 Hz project and audio device. Run this script again with the same source selected to replace the correction.")
else
  message("The correction could not be loaded. The new tracks were removed and the source settings restored. Check that ReaVerb is available; details are in the ReaScript console.")
end
